#include "PluginEditor.h"
namespace { const juce::Colour bg(0xff10131c), panel(0xff191d2b), ink(0xffedf0fa), muted(0xff989fb5), cyan(0xff69e6ef), pink(0xffe84fa8); }
VoxClarityEditor::VoxClarityEditor(VoxClarityProcessor& p):AudioProcessorEditor(&p),processor(p),diffAttachment(p.parameters,"diff",diff){setSize(640,430);title.setText("VOX  /  CLARITY",juce::dontSendNotification);title.setJustificationType(juce::Justification::centredLeft);title.setColour(juce::Label::textColourId,ink);title.setFont(juce::Font(23.f,juce::Font::bold));subtitle.setText("NEURAL VOICE CLEANUP  •  RNNOISE",juce::dontSendNotification);subtitle.setJustificationType(juce::Justification::centredLeft);subtitle.setColour(juce::Label::textColourId,muted);subtitle.setFont(juce::Font(11.f,juce::Font::bold));addAndMakeVisible(title);addAndMakeVisible(subtitle);addAndMakeVisible(diff);
 const std::array<const char*,4> ids{"strength","mix","gate","output"};const std::array<const char*,4> names{"STRENGTH","MIX","VOICE GATE","OUTPUT dB"};
 for(size_t i=0;i<sliders.size();++i){auto& s=sliders[i];s.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s.setTextBoxStyle(juce::Slider::TextBoxBelow,false,72,22);s.setNumDecimalPlacesToDisplay(i==3?1:0);s.setRotaryParameters(juce::MathConstants<float>::pi*1.25f,juce::MathConstants<float>::pi*2.75f,true);s.setColour(juce::Slider::rotarySliderFillColourId,i==0?pink:cyan);s.setColour(juce::Slider::thumbColourId,ink);s.setColour(juce::Slider::textBoxTextColourId,ink);s.setColour(juce::Slider::textBoxBackgroundColourId,panel);s.setColour(juce::Slider::textBoxOutlineColourId,juce::Colours::transparentBlack);labels[i].setText(names[i],juce::dontSendNotification);labels[i].setJustificationType(juce::Justification::centred);labels[i].setColour(juce::Label::textColourId,muted);labels[i].setFont(juce::Font(10.f,juce::Font::bold));addAndMakeVisible(s);addAndMakeVisible(labels[i]);attachments.push_back(std::make_unique<Attachment>(p.parameters,ids[i],s));}}
void VoxClarityEditor::paint(juce::Graphics& g){g.fillAll(bg);auto r=getLocalBounds().toFloat().reduced(9);g.setColour(panel);g.fillRoundedRectangle(r,18);g.setGradientFill(juce::ColourGradient(cyan.withAlpha(.18f),r.getTopLeft(),pink.withAlpha(.12f),r.getBottomRight(),false));g.fillRoundedRectangle(r.removeFromTop(104),18);g.setColour(juce::Colour(0xff34394d));g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(9),18,1.2f);auto orb=getLocalBounds().toFloat().withSizeKeepingCentre(145,145).translated(0,-35);g.setColour(pink.withAlpha(.12f));g.fillEllipse(orb.expanded(8));g.setColour(juce::Colour(0xff21273a));g.fillEllipse(orb);g.setColour(cyan.withAlpha(.7f));g.drawEllipse(orb.reduced(3),2.f);g.setColour(pink.withAlpha(.7f));g.drawEllipse(orb.reduced(10),1.f);g.setColour(ink);g.setFont(juce::Font(12.f,juce::Font::bold));g.drawFittedText("RN",orb.toNearestInt(),juce::Justification::centred,1);}
void VoxClarityEditor::resized(){auto a=getLocalBounds().reduced(28);a.removeFromTop(13);title.setBounds(a.removeFromTop(32).removeFromLeft(280));subtitle.setBounds(a.removeFromTop(19));diff.setBounds(a.getRight()-90,a.getY()-51,80,28);a.removeFromTop(128);const int w=a.getWidth()/4;for(size_t i=0;i<sliders.size();++i){juce::Rectangle<int> cell(a.getX()+int(i)*w,a.getY(),w,a.getHeight());labels[i].setBounds(cell.removeFromTop(22));sliders[i].setBounds(cell.reduced(8));}}
